import { AssignTaskUseCase } from '../../application/use-cases/AssignTaskUseCase';
import { CompleteTaskUseCase } from '../../application/use-cases/CompleteTaskUseCase';
import { CreateProjectUseCase } from '../../application/use-cases/CreateProjectUseCase';
import { CreateTaskUseCase } from '../../application/use-cases/CreateTaskUseCase';
import { CreateUserUseCase } from '../../application/use-cases/CreateUserUseCase';
import { ListProjectTasksUseCase } from '../../application/use-cases/ListProjectTasksUseCase';
import { TaskAssignmentService } from '../../domain/services/TaskAssignmentService';
import { ProjectController } from '../controllers/ProjectController';
import { TaskController } from '../controllers/TaskController';
import { UserController } from '../controllers/UserController';
import { Controllers } from '../http/createApp';
import { InMemoryProjectRepository } from '../repositories/InMemoryProjectRepository';
import { InMemoryTaskRepository } from '../repositories/InMemoryTaskRepository';
import { InMemoryUserRepository } from '../repositories/InMemoryUserRepository';
import { UuidIdGenerator } from '../services/UuidIdGenerator';

/** Composition root: wires in-memory adapters into use cases and controllers. */
export function buildControllers(): Controllers {
  const ids = new UuidIdGenerator();
  const users = new InMemoryUserRepository();
  const projects = new InMemoryProjectRepository();
  const tasks = new InMemoryTaskRepository();
  const assignment = new TaskAssignmentService(users);

  return {
    users: new UserController(new CreateUserUseCase(users, ids)),
    projects: new ProjectController(new CreateProjectUseCase(projects, ids)),
    tasks: new TaskController({
      createTask: new CreateTaskUseCase(projects, tasks, ids),
      listProjectTasks: new ListProjectTasksUseCase(projects, tasks),
      assignTask: new AssignTaskUseCase(tasks, assignment),
      completeTask: new CompleteTaskUseCase(tasks),
    }),
  };
}

